#[derive(Clone, Debug, Error, miette::Diagnostic, PartialEq, Eq)]
#[non_exhaustive]
pub enum VcsError {
    #[error("failed to discover Git repository at `{path}`: {message}")]
    #[diagnostic(code(E050), help("Ensure target directory is inside a valid Git repository."))]
    RepoNotFound { path: PathBuf, message: String },

    #[error("git error: {0}")]
    #[diagnostic(code(E051))]
    Git(String),

    #[error("reference `{ref_name}` was not found")]
    #[diagnostic(code(E052), help("Check if reference or tag exists in local or remote Git refs."))]
    RefNotFound { ref_name: String },

    #[error("tag glob pattern `{pattern}` is not a valid glob: {message}")]
    #[diagnostic(
        code(E053),
        help("Fix the glob syntax (e.g. balance `{{`/`}}` and `[`/`]`) or use a literal tag name.")
    )]
    InvalidGlob { pattern: String, message: String },

    /// Wraps a [`CommandError`] surfaced by the [`ShellGit`] (`CommandRunner`-
    /// shelled) backend -- e.g. the `git` binary itself couldn't be spawned.
    /// Kept `transparent` so callers that only care about the underlying
    /// `CommandError` (most of them, since it's the same error every direct
    /// `CommandRunner::run` call site already surfaces) can match through it.
    #[error(transparent)]
    Command(#[from] CommandError),
}

/// Narrows a [`VcsError`] to the Layer 1 [`CommitWalkError`] vocabulary at
/// the [`CommitWalker`] boundary.
///
/// [`CommitWalkError::Command`] and [`CommitWalkError::RefNotFound`] survive
/// as themselves -- they are the two distinctions consumers branch on. Every
/// other variant is gix- or repository-specific with no Layer 1 equivalent,
/// so it collapses into [`CommitWalkError::Backend`] carrying this error's
/// own `Display` rendering; nothing is lost from the message a user sees.
impl From<VcsError> for CommitWalkError {
    fn from(err: VcsError) -> Self {
        match err {
            VcsError::Command(inner) => CommitWalkError::Command(inner),
            VcsError::RefNotFound { ref_name } => CommitWalkError::RefNotFound { ref_name },
            other => CommitWalkError::Backend {
                message: other.to_string(),
            },
        }
    }
}

/// A commit as produced by a history walk.
///
/// Aliases [`callisto_model::CommitRecord`] rather than redeclaring it, so a
/// walk's output crosses the [`CommitWalker`] seam without a conversion and
/// there is exactly one definition of a commit's shape in the workspace.
pub type GitCommit = CommitRecord;

/// Compiles `pattern` into a [`globset::GlobMatcher`], surfacing a malformed
/// pattern as [`VcsError::InvalidGlob`] rather than letting it silently
/// disable filtering -- which would match every tag, a real correctness
/// risk for release tagging (a malformed tag template could make "last tag"
/// resolution pick an unrelated package's tag). The single shared
/// definition of "how do we compile a tag glob" across both
/// [`GitDataSource`] backends ([`GitRepository::list_tags`],
/// [`ShellGit::list_tags`]) and `callisto-graph`'s `tags::matching_tags`,
/// so all three filter tag names with byte-identical semantics.
pub fn compile_tag_glob(pattern: &str) -> Result<globset::GlobMatcher, VcsError> {
    globset::Glob::new(pattern)
        .map(|g| g.compile_matcher())
        .map_err(|e| VcsError::InvalidGlob {
            pattern: pattern.to_string(),
            message: e.to_string(),
        })
}

/// Whether [`GitDataSource::create_tag`] should let the ambient Git signing
/// configuration (`tag.gpgSign`/`commit.gpgsign`) apply, or force an
/// unsigned tag regardless of it.
///
/// Only [`ShellGit`]'s backend is affected: it shells out to the real `git`
/// binary, which consults process-visible Git config for signing.
/// [`GitRepository`]'s native `gix` backend constructs the tag object
/// directly and never signs either way, so both variants behave identically
/// there.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum TagSignPolicy {
    /// Let the repository's own Git config decide -- the right default for
    /// a human-run `callisto tag`.
    RespectRepoConfig,
    /// Always pass `--no-sign`, regardless of `tag.gpgSign`/`commit.gpgsign`.
    /// Some CI contexts set those globally (for commit signing) with no
    /// tag-signing key available; the durable release executor uses this to
    /// avoid failing there.
    ForceUnsigned,
}

/// Unified git-data access surface covering every operation callisto's
/// release-graph logic needs, independent of *how* the data is sourced.
///
/// Two backends implement this trait:
///
/// - [`GitRepository`] -- native `gix`. Fast, side-effect-free for reads,
///   but unavailable on `wasm32` ([`GitRepository::discover`] always
///   errors there -- gix is excluded from that target's deps).
/// - [`ShellGit`] -- shells out to real `git` via a
///   [`callisto_model::CommandRunner`], so it works everywhere a `git`
///   binary is reachable, including through the `wasm32`/Extism host
///   bridge.
///
/// Callers shouldn't implement or select between these directly; use
/// [`GitAccess::discover`], which tries native `gix` first and falls back
/// to the shell-out, applying the correct per-operation fallback policy
/// (see [`GitAccess`]'s docs).
pub trait GitDataSource {
    /// Returns the commit SHA that `HEAD` currently resolves to.
    fn head_sha(&self) -> Result<CommitSha, VcsError>;

    /// Lists tag names, optionally filtered by `glob` (a [`globset::Glob`]
    /// pattern). Both backends filter with the exact same `globset`
    /// matching semantics, so tag selection is byte-identical regardless of
    /// which one served the request. `None` matches every tag.
    fn list_tags(&self, glob: Option<&str>) -> Result<Vec<TagName>, VcsError>;

    /// Resolves `refname` (tag, branch, or partial/full SHA) to the commit
    /// it points at. An unresolvable ref is *not* an error -- it resolves
    /// to `Ok(None)`, which callers typically treat as "no bound" / "infer
    /// over full history".
    fn resolve_commit(&self, refname: &str) -> Result<Option<CommitSha>, VcsError>;

    /// Lists commits reachable from `HEAD`, down to (exclusive) `since_ref`
    /// when given, filtered to those that touch at least one of
    /// `pathspecs` (an empty slice disables filtering and returns every
    /// commit in the walk). Merge commits are always excluded, matching
    /// `git log --no-merges`.
    ///
    /// Unlike [`Self::resolve_commit`], a `since_ref` that's given but
    /// fails to resolve to a commit *is* an error: silently ignoring it and
    /// walking unbounded history instead of the caller's requested bound
    /// is a correctness bug (e.g. it can re-surface already-released
    /// commits into changelog/severity inference). `since_ref: None` is not
    /// this case -- it's a deliberate request for the full history and
    /// always succeeds.
    fn commits_since(&self, since_ref: Option<&str>, pathspecs: &[PathBuf]) -> Result<Vec<GitCommit>, VcsError>;

    /// Creates the tag `name` at `target_sha`: annotated with `message`
    /// when `Some`, lightweight when `None`. Fails if a ref of that name
    /// already exists.
    ///
    /// `sign` controls whether the ambient Git signing configuration is
    /// allowed to apply -- see [`TagSignPolicy`].
    ///
    /// Writes a git ref, so it requires an [`ApplyPermit`]; a dry run has
    /// none to give and therefore cannot call this at all.
    fn create_tag(
        &self,
        name: &str,
        target_sha: &CommitSha,
        message: Option<&str>,
        sign: TagSignPolicy,
        permit: &ApplyPermit,
    ) -> Result<(), VcsError>;

    /// Force-creates or -moves the floating tag `major_name` to point at
    /// `target_sha`, overwriting any existing ref of that name.
    ///
    /// Writes a git ref, so it requires an [`ApplyPermit`].
    fn create_floating_major(
        &self,
        major_name: &str,
        target_sha: &CommitSha,
        permit: &ApplyPermit,
    ) -> Result<(), VcsError>;
}

/// Wires a [`GitDataSource`] backend up to the Layer 1
/// [`callisto_model::CommitWalker`] contract.
///
/// The bodies are identical for every backend -- delegate `commits_since` and
/// narrow [`VcsError`] to [`CommitWalkError`] -- but they cannot be written
/// once as a blanket `impl<T: GitDataSource> CommitWalker for T`: `CommitWalker`
/// is foreign to this crate and `T` is uncovered, which the orphan rules
/// forbid. The macro keeps the repetition honest instead.
macro_rules! impl_commit_walker {
    ($ty:ty) => {
        impl CommitWalker for $ty {
            fn commits_since(
                &self,
                since_ref: Option<&str>,
                pathspecs: &[PathBuf],
            ) -> Result<Vec<CommitRecord>, CommitWalkError> {
                GitDataSource::commits_since(self, since_ref, pathspecs).map_err(Into::into)
            }
        }
    };
}

impl_commit_walker!(GitAccess<'_>);
impl_commit_walker!(GitRepository);
impl_commit_walker!(ShellGit<'_>);

/// Test-observability counter: total number of commits
/// [`GitRepository::commits_since_with_pathspec`]'s primary revwalk has
/// yielded (before merge/pathspec filtering). Production code never reads
/// this; it exists so tests can assert the walk is bounded to
/// `since..HEAD` rather than the whole repository history -- see
/// `crates/callisto-vcs/tests/revwalk_bound_count_test.rs`, isolated in its
/// own integration-test binary since this is a process-global counter (same
/// precedent as `callisto_manifests::open_call_count`).
static REVWALK_VISIT_COUNT: std::sync::atomic::AtomicUsize = std::sync::atomic::AtomicUsize::new(0);

/// Resets the internal revwalk-visit counter to zero. Intended for use in test setup.
pub fn reset_revwalk_visit_count() {
    REVWALK_VISIT_COUNT.store(0, std::sync::atomic::Ordering::SeqCst);
}

/// Reads the current value of the internal revwalk-visit counter.
pub fn revwalk_visit_count() -> usize {
    REVWALK_VISIT_COUNT.load(std::sync::atomic::Ordering::SeqCst)
}

pub struct GitRepository {
    #[cfg(not(target_arch = "wasm32"))]
    repo: gix::Repository,
}

impl GitRepository {
    #[cfg(not(target_arch = "wasm32"))]
    pub fn discover(path: impl AsRef<Path>) -> Result<Self, VcsError> {
        let p = path.as_ref();
        let clean_path = dunce::canonicalize(p).unwrap_or_else(|_| p.to_path_buf());
        let repo = gix::discover(&clean_path).map_err(|e| VcsError::RepoNotFound {
            path: clean_path,
            message: e.to_string(),
        })?;
        Ok(Self { repo })
    }

    #[cfg(target_arch = "wasm32")]
    pub fn discover(path: impl AsRef<Path>) -> Result<Self, VcsError> {
        Err(VcsError::RepoNotFound {
            path: path.as_ref().to_path_buf(),
            message: "gix native git operations disabled on WASM target".to_string(),
        })
    }

    pub fn head_sha(&self) -> Result<CommitSha, VcsError> {
        #[cfg(not(target_arch = "wasm32"))]
        {
            let head = self
                .repo
                .head_commit()
                .map_err(|e| VcsError::Git(format!("Failed to get HEAD commit: {e}")))?;
            CommitSha::parse(&head.id.to_hex().to_string()).map_err(|e| VcsError::Git(format!("Invalid HEAD SHA: {e}")))
        }
        #[cfg(target_arch = "wasm32")]
        {
            Err(VcsError::Git("WASM unsupported".to_string()))
        }
    }

    pub fn list_tags(&self, glob_pattern: Option<&str>) -> Result<Vec<TagName>, VcsError> {
        #[cfg(not(target_arch = "wasm32"))]
        {
            let platform = self
                .repo
                .references()
                .map_err(|e| VcsError::Git(format!("Failed to read references: {e}")))?;

            let mut tags = Vec::new();
            let tag_refs = platform
                .tags()
                .map_err(|e| VcsError::Git(format!("Failed to list tag refs: {e}")))?;

            // A pattern that fails to compile must not silently disable
            // filtering (which would match every tag in the repo -- a real
            // correctness risk for release tagging, since a malformed tag
            // template could then make "last tag" resolution pick an
            // unrelated package's tag). Surface it as an error instead;
            // `None` (no pattern requested at all) still means "match
            // everything".
            let matcher = glob_pattern.map(compile_tag_glob).transpose()?;

            for r in tag_refs.flatten() {
                let name = r.name().shorten().to_string();
                if let Some(ref m) = matcher {
                    if !m.is_match(&name) {
                        continue;
                    }
                }
                // A ref name Git itself created is always a legal ref, but
                // "legal Git ref" does not imply "safe to hand to a CLI
                // parser as a bare positional" (a leading `-` is legal but
                // reads as a flag) -- skip anything `TagName::parse` would
                // reject rather than propagate an unsafe name into "last
                // tag" resolution.
                if let Ok(tag) = TagName::parse(&name) {
                    tags.push(tag);
                }
            }

            Ok(tags)
        }
        #[cfg(target_arch = "wasm32")]
        {
            let _unused = glob_pattern;
            Ok(Vec::new())
        }
//! Central native-`gix`-first, `CommandRunner`-shell-fallback selection
//! logic for [`GitDataSource`].

use std::path::{Path, PathBuf};

use callisto_model::{ApplyPermit, CommandRunner, CommitSha, StagedChangeV1, TagName};

use crate::{GitCommit, GitDataSource, GitRepository, ShellGit, VcsError};

/// Selects between native `gix` ([`GitRepository`]) and a `CommandRunner`
/// shell-out ([`ShellGit`]) per operation, so callers never branch on it.
///
/// Construct via [`GitAccess::discover`], then call [`GitDataSource`]
/// methods directly.
///
/// **Fallback policy differs by operation category, deliberately:**
///
/// - **Reads** ([`GitDataSource::list_tags`], [`GitDataSource::resolve_commit`],
///   [`GitDataSource::commits_since`]): fall back to shell on *any* `gix`
///   error (failed discovery, or a discovered repo's op failing) --
///   retrying a read can only help.
/// - **Writes** ([`GitDataSource::create_tag`], [`GitDataSource::create_floating_major`]):
///   fall back *only* if `gix` was never discovered. A discovered repo's
///   result is authoritative -- retrying a failed mutation through a
///   different path risks masking a real failure, or double-applying a
///   partial mutation.
pub struct GitAccess<'r> {
    native: Option<GitRepository>,
    shell: ShellGit<'r>,
}

/// Fresh Git checkout facts used to bind a durable release intent to the
/// exact repository it was validated against.
///
/// This is intentionally evidence, not a lossy `bool`: consumers must retain
/// the canonical root and complete `HEAD` they compare to source identity.
/// Its fields are private so only the VCS observation path can construct it.
#[derive(Debug, PartialEq, Eq)]
pub struct GitCommitTrustEvidence {
    canonical_root: PathBuf,
    head: CommitSha,
    head_disposition: GitHeadDisposition,
    allowed_ignored_paths: Vec<PathBuf>,
}

impl GitCommitTrustEvidence {
    pub(crate) fn new(
        canonical_root: PathBuf,
        head: CommitSha,
        head_disposition: GitHeadDisposition,
        allowed_ignored_paths: Vec<PathBuf>,
    ) -> Self {
        Self {
            canonical_root,
            head,
            head_disposition,
            allowed_ignored_paths,
        }
    }

    pub fn canonical_root(&self) -> &Path {
        &self.canonical_root
    }

    pub fn head(&self) -> &CommitSha {
        &self.head
    }

    pub fn head_disposition(&self) -> GitHeadDisposition {
        self.head_disposition
    }

    pub fn allowed_ignored_paths(&self) -> &[PathBuf] {
        &self.allowed_ignored_paths
    }
}

/// Whether `HEAD` was attached to a symbolic reference when it was observed.
/// A detached checkout is valid when its full [`CommitSha`] matches the
/// release intent's source identity.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum GitHeadDisposition {
    Attached,
    Detached,
}

impl<'r> GitAccess<'r> {
    /// Tries to discover a native `gix` repository at `root`; regardless of
    /// whether that succeeds, also prepares the `CommandRunner`-shelled
    /// backend against the same `root`, ready to serve as a fallback (reads)
    /// or as the sole backend (writes, when discovery failed).
    ///
    /// Never fails: a discovery failure just means every operation runs
    /// through the shell backend instead, exactly as it unconditionally
    /// does on `wasm32` (gix is excluded from that target's dependency set,
    /// so [`GitRepository::discover`] always returns `Err` there).
    pub fn discover(root: impl AsRef<Path>, runner: &'r dyn CommandRunner) -> Self {
        let root = root.as_ref();
        GitAccess {
            native: GitRepository::discover(root).ok(),
            shell: ShellGit::new(runner, root.to_path_buf()),
        }
    }

    /// Re-observes the root, full commit, symbolic-HEAD state, and worktree
    /// through the shell backend. These facts must never come from a native
    /// repository handle cached before final release validation.
    pub fn observe_git_commit_trust(&self) -> Result<GitCommitTrustEvidence, VcsError> {
        self.shell.observe_git_commit_trust()
    }

    /// Returns every staged (Git index) change relative to `base`. Shell-only:
    /// no native `gix` backend lists changed paths or reads blobs today.
    pub fn staged_changes_since(&self, base: &CommitSha) -> Result<Vec<StagedChangeV1>, VcsError> {
        self.shell.staged_changes_since(base)
    }

    /// Shared READ fallback policy (see module doc): try native `gix` first
    /// if discovered, falling back to the shell on *any* error -- including
    /// discovery having failed in the first place. Never called by a WRITE
    /// method, whose authoritative-native-result policy is the opposite of
    /// this one.
    fn read_with_fallback<T>(
        &self,
        native: impl FnOnce(&GitRepository) -> Result<T, VcsError>,
        shell: impl FnOnce() -> Result<T, VcsError>,
    ) -> Result<T, VcsError> {
        if let Some(repo) = &self.native {
            if let Ok(value) = native(repo) {
                return Ok(value);
            }
        }
        shell()
    }
}

impl GitDataSource for GitAccess<'_> {
    fn head_sha(&self) -> Result<CommitSha, VcsError> {
        self.read_with_fallback(|repo| repo.head_sha(), || self.shell.head_sha())
    }

    fn list_tags(&self, glob: Option<&str>) -> Result<Vec<TagName>, VcsError> {
        self.read_with_fallback(|repo| repo.list_tags(glob), || self.shell.list_tags(glob))
    }

    fn resolve_commit(&self, refname: &str) -> Result<Option<CommitSha>, VcsError> {
        self.read_with_fallback(
            |repo| repo.resolve_commit(refname),
            || self.shell.resolve_commit(refname),
        )
    }

    fn commits_since(&self, since_ref: Option<&str>, pathspecs: &[PathBuf]) -> Result<Vec<GitCommit>, VcsError> {
        self.read_with_fallback(
            |repo| repo.commits_since(since_ref, pathspecs),
            || self.shell.commits_since(since_ref, pathspecs),
        )
    }

    fn create_tag(
        &self,
        name: &str,
        target_sha: &CommitSha,
        message: Option<&str>,
        sign: crate::TagSignPolicy,
        permit: &ApplyPermit,
    ) -> Result<(), VcsError> {
        if let Some(repo) = &self.native {
            // Authoritative: a genuine gix failure must not be masked by
            // silently retrying through the shell.
            return repo.create_tag(name, target_sha, message, sign, permit);
        }
        self.shell.create_tag(name, target_sha, message, sign, permit)
    }

    fn create_floating_major(
        &self,
        major_name: &str,
        target_sha: &CommitSha,
        permit: &ApplyPermit,
    ) -> Result<(), VcsError> {
        if let Some(repo) = &self.native {
            return repo.create_floating_major(major_name, target_sha, permit);
        }
        self.shell.create_floating_major(major_name, target_sha, permit)
    }
}

