    #[cfg(not(target_arch = "wasm32"))]
    pub fn discover(path: impl AsRef<Path>) -> Result<Self, VcsError> {
        let p = path.as_ref();
        let clean_path = dunce::canonicalize(p).unwrap_or_else(|_| p.to_path_buf());
        let repo = gix::discover(&clean_path).map_err(|e| VcsError::RepoNotFound {
            path: clean_path,
            message: e.to_string(),
        })?;
        Ok(Self { repo })
    }

    #[cfg(target_arch = "wasm32")]
    pub fn discover(path: impl AsRef<Path>) -> Result<Self, VcsError> {
        Err(VcsError::RepoNotFound {
            path: path.as_ref().to_path_buf(),
            message: "gix native git operations disabled on WASM target".to_string(),
        })
    }

    pub fn head_sha(&self) -> Result<CommitSha, VcsError> {
        #[cfg(not(target_arch = "wasm32"))]
        {
            let head = self
                .repo
                .head_commit()
                .map_err(|e| VcsError::Git(format!("Failed to get HEAD commit: {e}")))?;
            CommitSha::parse(&head.id.to_hex().to_string()).map_err(|e| VcsError::Git(format!("Invalid HEAD SHA: {e}")))
        }
        #[cfg(target_arch = "wasm32")]
        {
            Err(VcsError::Git("WASM unsupported".to_string()))
        }
    }

    pub fn list_tags(&self, glob_pattern: Option<&str>) -> Result<Vec<TagName>, VcsError> {
        #[cfg(not(target_arch = "wasm32"))]
        {
            let platform = self
                .repo
                .references()
                .map_err(|e| VcsError::Git(format!("Failed to read references: {e}")))?;

            let mut tags = Vec::new();
            let tag_refs = platform
                .tags()
                .map_err(|e| VcsError::Git(format!("Failed to list tag refs: {e}")))?;

            // A pattern that fails to compile must not silently disable
            // filtering (which would match every tag in the repo -- a real
            // correctness risk for release tagging, since a malformed tag
            // template could then make "last tag" resolution pick an
            // unrelated package's tag). Surface it as an error instead;
            // `None` (no pattern requested at all) still means "match
            // everything".
            let matcher = glob_pattern.map(compile_tag_glob).transpose()?;

            for r in tag_refs.flatten() {
                let name = r.name().shorten().to_string();
                if let Some(ref m) = matcher {
                    if !m.is_match(&name) {
                        continue;
                    }
                }
                // A ref name Git itself created is always a legal ref, but
                // "legal Git ref" does not imply "safe to hand to a CLI
                // parser as a bare positional" (a leading `-` is legal but
                // reads as a flag) -- skip anything `TagName::parse` would
                // reject rather than propagate an unsafe name into "last
                // tag" resolution.
                if let Ok(tag) = TagName::parse(&name) {
                    tags.push(tag);
                }
            }

            Ok(tags)
        }
        #[cfg(target_arch = "wasm32")]
        {
            let _unused = glob_pattern;
            Ok(Vec::new())
        }
    }

    /// Resolves an arbitrary ref (tag, branch, or partial SHA) to the commit
    /// SHA it points at.
    ///
    /// Follows the same resolution and error-handling convention as the
    /// `from_ref` handling inside [`Self::commits_since`]: an unresolvable
    /// ref (missing tag, unborn repo, ref pointing at a non-commit object
    /// that can't be peeled to one, etc.) is not an error condition -- it
    /// degrades gracefully to `Ok(None)`, which callers treat as "no bound"
    /// / "infer over full history".
    pub fn resolve_commit(&self, refname: &str) -> Result<Option<CommitSha>, VcsError> {
        #[cfg(not(target_arch = "wasm32"))]
        {
            let Ok(spec) = self.repo.rev_parse_single(refname) else {
                return Ok(None);
            };
            let Ok(object) = spec.object() else {
                return Ok(None);
            };
            let Ok(commit) = object.peel_to_kind(gix::object::Kind::Commit) else {
                return Ok(None);
            };

            let hex = commit.id.to_hex().to_string();
            let sha = CommitSha::parse(&hex).map_err(|e| VcsError::Git(format!("Invalid commit SHA: {e}")))?;
            Ok(Some(sha))
        }
        #[cfg(target_arch = "wasm32")]
        {
            let _unused = refname;
            Ok(None)
        }
    }

    /// Like [`Self::commits_since`], but filters to commits touching at
    /// least one path under one of `pathspecs`.
    ///
    /// `pathspecs` match as directory/path prefixes against a commit's tree
    /// diff vs. its first parent -- mirrors `git log -- <pathspecs>`'s
    /// scoping, not full git pathspec magic (`:!`, globs, etc). Empty
    /// `pathspecs` disables filtering (all commits, like `git log` with no
    /// trailing `--`).
    ///
    /// `since` is exclusive, same as `commits_since`. Merge commits are
    /// skipped (`--no-merges`), since a merge's message duplicates work its
    /// non-merge ancestors already represent -- this powers per-package
    /// commit scoping for severity inference.
    pub fn commits_since_with_pathspec(
        &self,
        since: Option<&CommitSha>,
        pathspecs: &[PathBuf],
    ) -> Result<Vec<GitCommit>, VcsError> {
        #[cfg(not(target_arch = "wasm32"))]
        {
            let head = self
                .repo
                .head_commit()
                .map_err(|e| VcsError::Git(format!("Failed to get HEAD commit: {e}")))?;

            let mut platform = self.repo.rev_walk(vec![head.id]);

            // Bound the walk with gix's own hidden-tip frontier algorithm
            // (`git log since..HEAD` semantics) instead of a second,
            // unbounded full-history walk from `since` collected into an
            // exclusion set. `with_hidden` paints the overlap between the
            // visible (HEAD) and hidden (`since`) tips using generation
            // numbers and refuses to enqueue parents once a commit is known
            // to be hidden-only ancestry, so the walk stops once every
            // in-flight branch has been resolved instead of continuing to
            // the repository's first commit. This preserves the same
            // branchy-history correctness the old two-walk-then-exclude
            // approach needed a manual `continue`-not-`break` exclusion set
            // for (a topological walk can visit `since` before it has
            // emitted all commits on branches that diverged before it) --
            // gix's frontier computation is exactly the same "boundary
            // commit" algorithm `git rev-list branch ^tag` itself uses, so
            // it handles that case internally rather than needing it
            // reimplemented here. `since` remains exclusive, matching the
            // prior behavior: `with_hidden` excludes both the hidden tip
            // itself and everything reachable from it.
            if let Some(s) = since {
                let since_oid = gix::ObjectId::from_hex(s.as_ref().as_bytes())
                    .map_err(|e| VcsError::Git(format!("Invalid since SHA: {e}")))?;
                platform = platform.with_hidden(Some(since_oid));
            }

            let revwalk = platform
                .all()
                .map_err(|e| VcsError::Git(format!("Failed to create revwalk: {e}")))?;

            let mut commits = Vec::new();
            for info in revwalk {
                let info = info.map_err(|e| VcsError::Git(e.to_string()))?;
                REVWALK_VISIT_COUNT.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
                let hex = info.id.to_hex().to_string();

                if info.parent_ids().count() > 1 {
                    continue;
                }

                let commit_obj = info
                    .object()
                    .map_err(|e| VcsError::Git(format!("Failed to load commit object: {e}")))?;

                if !pathspecs.is_empty() {
                    let touched = commit_touches_pathspecs(&self.repo, &info, &commit_obj, pathspecs)?;
                    if !touched {
                        continue;
                    }
                }

                let sha = CommitSha::parse(&hex).map_err(|e| VcsError::Git(format!("Invalid commit SHA: {e}")))?;

                let message = commit_obj.message().map_err(|e| VcsError::Git(e.to_string()))?;
                let summary = message.title.to_string().replace("\r\n", "\n").trim_end().to_string();
                let body = message.body.map(|b| b.to_string().replace("\r\n", "\n"));

                commits.push(GitCommit { sha, summary, body });
            }

            Ok(commits)
        }
        #[cfg(target_arch = "wasm32")]
        {
            let _unused = (since, pathspecs);
            Ok(Vec::new())
        }
    }

    /// `sign` is accepted for interface parity with [`ShellGit::create_tag`]
    /// but has no effect here: this constructs the tag object directly via
    /// `gix`, which never shells out to `git` and so never consults
    /// `tag.gpgSign`/`commit.gpgsign` in the first place.
    pub fn create_tag(
        &self,
        name: &str,
        target_sha: &CommitSha,
        message: Option<&str>,
        _sign: TagSignPolicy,
        _permit: &ApplyPermit,
    ) -> Result<(), VcsError> {
        #[cfg(not(target_arch = "wasm32"))]
        {
            let oid = gix::ObjectId::from_hex(target_sha.as_ref().as_bytes())
                .map_err(|e| VcsError::Git(format!("Invalid SHA: {e}")))?;

            if let Some(msg) = message {
                self.repo
                    .tag(
                        name,
                        oid,
                        gix::object::Kind::Commit,
                        None,
                        msg,
                        gix::refs::transaction::PreviousValue::MustNotExist,
                    )
                    .map_err(|e| VcsError::Git(format!("Failed to create tag: {e}")))?;
            } else {
                let clean_name = name.strip_prefix("refs/tags/").unwrap_or(name);
                let ref_name = format!("refs/tags/{}", clean_name);
                let _unused = self
                    .repo
                    .reference(
                        ref_name,
                        oid,
                        gix::refs::transaction::PreviousValue::MustNotExist,
                        "callisto create tag",
                    )
                    .map_err(|e| VcsError::Git(format!("Failed to create lightweight tag: {e}")))?;
            }
            Ok(())
        }
        #[cfg(target_arch = "wasm32")]
        {
            let _ = (name, target_sha, message);
            Err(VcsError::Git("WASM unsupported".to_string()))
        }
    }

    pub fn create_floating_major(
        &self,
        major_name: &str,
        target_sha: &CommitSha,
        _permit: &ApplyPermit,
    ) -> Result<(), VcsError> {
        #[cfg(not(target_arch = "wasm32"))]
        {
            let oid = gix::ObjectId::from_hex(target_sha.as_ref().as_bytes())
                .map_err(|e| VcsError::Git(format!("Invalid SHA: {e}")))?;

            let ref_name = format!("refs/tags/{}", major_name);
            let _unused = self
                .repo
                .reference(
                    ref_name,
                    oid,
                    gix::refs::transaction::PreviousValue::Any,
                    "callisto floating major",
                )
                .map_err(|e| VcsError::Git(format!("Failed to update floating major: {e}")))?;

            Ok(())
        }
        #[cfg(target_arch = "wasm32")]
        {
            let _ = (major_name, target_sha);
            Err(VcsError::Git("WASM unsupported".to_string()))
        }
    }
}

/// Diffs `commit_obj`'s tree against its first parent's tree (or the empty
/// tree, for a root commit) and reports whether any changed path falls
/// under one of `pathspecs`.
#[cfg(not(target_arch = "wasm32"))]
fn commit_touches_pathspecs(
    repo: &gix::Repository,
    info: &gix::revision::walk::Info<'_>,
    commit_obj: &gix::Commit<'_>,
    pathspecs: &[PathBuf],
) -> Result<bool, VcsError> {
    let commit_tree = commit_obj
        .tree()
        .map_err(|e| VcsError::Git(format!("Failed to load commit tree: {e}")))?;

    let parent_tree = match info.parent_ids().next() {
        Some(parent_id) => {
            let parent_commit = parent_id
                .object()
                .map_err(|e| VcsError::Git(format!("Failed to load parent commit object: {e}")))?
                .into_commit();
            parent_commit
                .tree()
                .map_err(|e| VcsError::Git(format!("Failed to load parent tree: {e}")))?
        }
        None => repo.empty_tree(),
    };

    let mut touched = false;
    let mut platform = parent_tree
        .changes()
        .map_err(|e| VcsError::Git(format!("Failed to initialize tree diff: {e}")))?;
    // Rewrite (rename/copy) detection needs blob-similarity computation we
    // don't otherwise need: pathspec matching only cares about which paths
    // changed, not whether they're related across a rename.
    platform.options(|o| {
        o.track_rewrites(None);
    });
    // Note: we deliberately always return `Continue` here, never `Break` --
    // gix's tree-diff machinery treats an early `Break` as a cancellation
    // and surfaces it as an `Err` from `for_each_to_obtain_tree`, which
    // would turn "found a match" into a spurious failure.
    platform
        .for_each_to_obtain_tree(&commit_tree, |change| {
            if change_matches_pathspecs(&change, pathspecs) {
                touched = true;
            }
            Ok::<_, std::convert::Infallible>(std::ops::ControlFlow::Continue(()))
        })
        .map_err(|e| VcsError::Git(format!("Failed to diff commit tree: {e}")))?;

    Ok(touched)
}

#[cfg(not(target_arch = "wasm32"))]
fn change_matches_pathspecs(change: &gix::object::tree::diff::Change<'_, '_, '_>, pathspecs: &[PathBuf]) -> bool {
    use gix::object::tree::diff::Change;
    match change {
        Change::Addition { location, .. }
        | Change::Deletion { location, .. }
        | Change::Modification { location, .. } => location_matches(location, pathspecs),
        Change::Rewrite {
            location,
            source_location,
            ..
        } => location_matches(location, pathspecs) || location_matches(source_location, pathspecs),
    }
}

/// Simple directory/path-prefix pathspec match: a changed path matches a
/// pathspec if it's exactly equal to it, or nested underneath it as a
/// directory prefix. Does not implement full git pathspec magic syntax.
///
/// `"."` is a special case, not a literal prefix: it's the sentinel
/// `changed::package_paths` emits for a manifest living at the workspace/
/// package root (e.g. a single-package repo's `Cargo.toml`), matching real
/// `git log -- .`'s own semantics for the current-directory pathspec. Rust's
/// `Path::starts_with` does not treat `.` as a universal prefix
/// (`Path::new("Cargo.toml").starts_with(".")` is `false`), so without this
/// case a root-level pathspec would silently match zero commits instead of
/// every commit -- making commit-based inference a total no-op for exactly
/// the single-package repos most likely to rely on it.
#[cfg(not(target_arch = "wasm32"))]
fn location_matches(location: &gix::bstr::BStr, pathspecs: &[PathBuf]) -> bool {
    let path_str = String::from_utf8_lossy(location);
    let changed_path = Path::new(path_str.as_ref());
    pathspecs.iter().any(|spec| {
        spec.as_path() == Path::new(".") || changed_path == spec.as_path() || changed_path.starts_with(spec)
    })
        sign: crate::TagSignPolicy,
        _permit: &ApplyPermit,
    ) -> Result<(), VcsError> {
        // `--` marks the end of option parsing so `name` (validated
        // upstream by `is_valid_git_ref_name`, but defended here too) can
        // never be misread as a `git tag` flag even if it started with `-`.
        let mut args: Vec<&str> = vec!["tag"];
        if let Some(msg) = message {
            args.extend(["-a", "-m", msg]);
        }
        if matches!(sign, crate::TagSignPolicy::ForceUnsigned) {
            args.push("--no-sign");
        }
        args.extend(["--", name, target_sha.as_str()]);
        let output = self.runner.run("git", &args, &self.root)?;
        if !output.success() {
            return Err(VcsError::Git(format!(
                "`git tag` failed in `{}`: {}",
                self.root.display(),
                output.redacted_stderr()
            )));
        }
        Ok(())
    }

    fn create_floating_major(
        &self,
        major_name: &str,
        target_sha: &CommitSha,
        _permit: &ApplyPermit,
    ) -> Result<(), VcsError> {
        let output = self
            .runner
            .run("git", &["tag", "-f", "--", major_name, target_sha.as_str()], &self.root)?;
        if !output.success() {
            return Err(VcsError::Git(format!(
                "`git tag -f` failed in `{}`: {}",
                self.root.display(),
                output.redacted_stderr()
            )));
        }
        Ok(())
    }
}

/// Parses the `<RECORD_SEP>%H<FIELD_SEP>%B`-formatted `git log` output
/// produced by [`ShellGit::commits_since`] into [`GitCommit`]s, splitting
/// each raw message on its first blank line into `summary`/`body` --
/// mirroring how `gix`'s own commit-message parsing (used by
/// `GitRepository::commits_since_with_pathspec`) splits title from body,
/// so both backends hand callers the same shape.
fn parse_git_log_output(stdout: &str, cwd: &Path) -> Result<Vec<GitCommit>, VcsError> {
    let mut commits = Vec::new();

    for record in stdout.split(RECORD_SEP) {
        // `tformat:`-style `--format=` output (the default when the format
        // string doesn't start with `format:`/`tformat:`) appends a
        // trailing newline after every entry; strip it rather than the
        // message's own content.
        let record = record.trim_end_matches('\n');
        if record.is_empty() {
            continue;
        }

        let Some((sha_str, message)) = record.split_once(FIELD_SEP) else {
            return Err(VcsError::Git(format!(
                "could not parse `git log` output in `{}` into commit records: expected a \
                 `<sha>{FIELD_SEP:?}<message>` record, got: {record:?}",
                cwd.display()
            )));
        };

        let sha = CommitSha::parse(sha_str).map_err(|e| {
            VcsError::Git(format!(
                "could not parse `git log` output in `{}`: invalid commit SHA `{sha_str}`: {e}",
                cwd.display()
            ))
        })?;

        let message = message.replace("\r\n", "\n");
        let (summary, body) = match message.split_once("\n\n") {
            Some((title, rest)) => (title.trim_end().to_string(), Some(rest.to_string())),
            None => (message.trim_end().to_string(), None),
        };

        commits.push(GitCommit { sha, summary, body });
    }

    Ok(commits)
}

#[cfg(test)]
mod tests {

    /// Tests exercise the write primitives directly rather than through a
    /// command handler, so they mint a permit without a dry-run flag to
    /// consult. Every non-test caller must go through
    /// `ApplyPermit::granted_unless_dry_run`.
    fn permit() -> callisto_model::ApplyPermit {
        callisto_model::ApplyPermit::force_for_tests()
    }
    use super::*;
    use callisto_model::{CommandError, CommandOutput};
    use std::sync::Mutex;

    type ResponseFn = dyn Fn(&[&str]) -> Result<CommandOutput, CommandError> + Send + Sync;

    struct FakeRunner {
        calls: Mutex<Vec<Vec<String>>>,
        response: Box<ResponseFn>,
    }

    impl CommandRunner for FakeRunner {
        fn run(&self, program: &str, args: &[&str], _cwd: &Path) -> Result<CommandOutput, CommandError> {
            assert_eq!(program, "git");
            self.calls
                .lock()
                .unwrap()
                .push(args.iter().map(|s| s.to_string()).collect());
            (self.response)(args)
        }
    }

    fn ok(stdout: impl Into<String>) -> CommandOutput {
        CommandOutput {
            exit_code: Some(0),
            stdout: stdout.into(),
            stderr: String::new(),
        }
    }

    fn trust_response(root: PathBuf, status: String, detached: bool) -> Box<ResponseFn> {
        Box::new(move |args| match args {
            ["rev-parse", "--show-toplevel"] => Ok(ok(format!("{}\n", root.display()))),
            ["rev-parse", "--show-object-format"] => Ok(ok("sha1\n")),
            ["rev-parse", "--is-shallow-repository"] => Ok(ok("false\n")),
            ["rev-parse", "--verify", "HEAD^{commit}"] => Ok(ok(format!("{}\n", "a".repeat(40)))),
            ["symbolic-ref", "--quiet", "HEAD"] if detached => Ok(CommandOutput {
                exit_code: Some(1),
                stdout: String::new(),
                stderr: String::new(),
            }),
            ["symbolic-ref", "--quiet", "HEAD"] => Ok(ok("refs/heads/main\n")),
            ["status", "--porcelain=v1", "-z", "--untracked-files=all", "--ignored=matching"] => Ok(ok(status.clone())),
            other => panic!("unexpected Git trust command: {other:?}"),
        })
    }

    #[test]
    fn git_commit_trust_evidence_is_root_bound_and_allows_only_fixed_ignored_paths() {
        let temp = tempfile::tempdir().unwrap();
        let expected_root = dunce::canonicalize(temp.path()).unwrap();
        let runner = FakeRunner {
            calls: Mutex::new(Vec::new()),
            response: trust_response(
                temp.path().to_path_buf(),
                "!! target/debug/callisto\0!! .moon/cache/state\0".to_string(),
                true,
            ),
        };
        let git = ShellGit::new(&runner, temp.path());

        let evidence = git.observe_git_commit_trust().unwrap();

        assert_eq!(evidence.canonical_root(), expected_root);
        assert_eq!(evidence.head().as_str(), "a".repeat(40));
        assert_eq!(evidence.head_disposition(), GitHeadDisposition::Detached);
        assert_eq!(
            evidence.allowed_ignored_paths(),
            &[
                PathBuf::from(".moon/cache/state"),
                PathBuf::from("target/debug/callisto")
            ]
        );
    }

