    pub fn create_tag(
        &self,
        name: &str,
        target_sha: &CommitSha,
        message: Option<&str>,
        _sign: TagSignPolicy,
        _permit: &ApplyPermit,
    ) -> Result<(), VcsError> {
        #[cfg(not(target_arch = "wasm32"))]
        {
            let oid = gix::ObjectId::from_hex(target_sha.as_ref().as_bytes())
                .map_err(|e| VcsError::Git(format!("Invalid SHA: {e}")))?;

            if let Some(msg) = message {
                self.repo
                    .tag(
                        name,
                        oid,
