    #[gix_protocol::bisync::bisync]
    pub async fn ref_map(
        self,
        progress: impl Progress,
        options: Options,
    ) -> Result<(fetch::RefMap, gix_protocol::Handshake), Error> {
        let repo = self.remote.repo;
        self.into_detached().ref_map(repo, progress, options).await
    }
