/// Narrows a [`VcsError`] to the Layer 1 [`CommitWalkError`] vocabulary at
/// the [`CommitWalker`] boundary.
///
/// [`CommitWalkError::Command`] and [`CommitWalkError::RefNotFound`] survive
/// as themselves -- they are the two distinctions consumers branch on. Every
/// other variant is gix- or repository-specific with no Layer 1 equivalent,
/// so it collapses into [`CommitWalkError::Backend`] carrying this error's
/// own `Display` rendering; nothing is lost from the message a user sees.
impl From<VcsError> for CommitWalkError {
    fn from(err: VcsError) -> Self {
        match err {
            VcsError::Command(inner) => CommitWalkError::Command(inner),
            VcsError::RefNotFound { ref_name } => CommitWalkError::RefNotFound { ref_name },
            other => CommitWalkError::Backend {
                message: other.to_string(),
            },
        }
    }
}

/// A commit as produced by a history walk.
///
/// Aliases [`callisto_model::CommitRecord`] rather than redeclaring it, so a
/// walk's output crosses the [`CommitWalker`] seam without a conversion and
/// there is exactly one definition of a commit's shape in the workspace.
pub type GitCommit = CommitRecord;

/// Compiles `pattern` into a [`globset::GlobMatcher`], surfacing a malformed
/// pattern as [`VcsError::InvalidGlob`] rather than letting it silently
/// disable filtering -- which would match every tag, a real correctness
/// risk for release tagging (a malformed tag template could make "last tag"
/// resolution pick an unrelated package's tag). The single shared
/// definition of "how do we compile a tag glob" across both
/// [`GitDataSource`] backends ([`GitRepository::list_tags`],
/// [`ShellGit::list_tags`]) and `callisto-graph`'s `tags::matching_tags`,
/// so all three filter tag names with byte-identical semantics.
pub fn compile_tag_glob(pattern: &str) -> Result<globset::GlobMatcher, VcsError> {
    globset::Glob::new(pattern)
        .map(|g| g.compile_matcher())
        .map_err(|e| VcsError::InvalidGlob {
            pattern: pattern.to_string(),
            message: e.to_string(),
        })
}

/// Whether [`GitDataSource::create_tag`] should let the ambient Git signing
/// configuration (`tag.gpgSign`/`commit.gpgsign`) apply, or force an
/// unsigned tag regardless of it.
///
/// Only [`ShellGit`]'s backend is affected: it shells out to the real `git`
/// binary, which consults process-visible Git config for signing.
/// [`GitRepository`]'s native `gix` backend constructs the tag object
/// directly and never signs either way, so both variants behave identically
/// there.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum TagSignPolicy {
    /// Let the repository's own Git config decide -- the right default for
    /// a human-run `callisto tag`.
    RespectRepoConfig,
    /// Always pass `--no-sign`, regardless of `tag.gpgSign`/`commit.gpgsign`.
    /// Some CI contexts set those globally (for commit signing) with no
    /// tag-signing key available; the durable release executor uses this to
    /// avoid failing there.
    ForceUnsigned,
}

/// Unified git-data access surface covering every operation callisto's
/// release-graph logic needs, independent of *how* the data is sourced.
///
/// Two backends implement this trait:
///
/// - [`GitRepository`] -- native `gix`. Fast, side-effect-free for reads,
///   but unavailable on `wasm32` ([`GitRepository::discover`] always
///   errors there -- gix is excluded from that target's deps).
/// - [`ShellGit`] -- shells out to real `git` via a
///   [`callisto_model::CommandRunner`], so it works everywhere a `git`
///   binary is reachable, including through the `wasm32`/Extism host
///   bridge.
///

item.formatted_output:
    fn observe_remote_annotated_tag(
        &self,
        remote: &str,
        name: &TagName,
        target_sha: &CommitSha,
        annotation_digest: &TagAnnotationDigest,
    ) -> Result<RemoteAnnotatedTagObservation, VcsError> {
        // gix's local repository handle has no complete remote annotation
        // protocol. Its explicit implementation returns an unsupported VCS
        // error, so this read follows the standard safe read fallback and
        // ShellGit performs one canonical remote observation.
        self.read_with_fallback(
            |repo| repo.observe_remote_annotated_tag(remote, name, target_sha, annotation_digest),
            || {
                self.shell
                    .observe_remote_annotated_tag(remote, name, target_sha, annotation_digest)
            },
        )
    }

    fn push_annotated_tag_and_confirm(
        &self,
        remote: &str,
        name: &TagName,
        target_sha: &CommitSha,
        annotation_digest: &TagAnnotationDigest,
        permit: &ApplyPermit,
    ) -> Result<RemoteAnnotatedTagObservation, VcsError> {
        // Push is a mutation and must be paired with the shell transport's
        // mandatory remote readback. Do not try native first: gix cannot
        // provide that paired protocol, and a retry could double-apply it.
        self.shell
            .push_annotated_tag_and_confirm(remote, name, target_sha, annotation_digest, permit)
    }
}

