use std::fmt;
use std::path::{Path, PathBuf};

use callisto_model::{ApplyPermit, CommandError, CommitRecord, CommitSha, CommitWalkError, CommitWalker, TagName};
use sha2::{Digest, Sha256};
use thiserror::Error;

pub mod access;
pub mod release_lock;
pub mod shell;

pub use access::GitAccess;
pub use shell::ShellGit;

/// SHA-256 of the canonical message bytes in an annotated Git tag.
///
/// `git tag -m` stores a final newline after its message. Release callers
/// construct this value from the logical annotation they pass to
/// [`GitDataSource::create_tag`], while remote observation hashes the raw
/// message bytes in the fetched tag object. Keeping that conversion here
/// prevents the graph layer from having a second, subtly different notion of
/// annotated-tag equality.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub struct TagAnnotationDigest(String);

impl TagAnnotationDigest {
    /// Hashes an annotation as Git stores the ordinary `git tag -m` message.
    pub fn from_annotation(annotation: &str) -> Self {
        let mut bytes = annotation.trim_end_matches(['\r', '\n']).as_bytes().to_vec();
        bytes.push(b'\n');
        Self(format!("{:x}", Sha256::digest(bytes)))
    }

    /// Hashes raw annotation bytes from a parsed annotated tag object.
    pub fn from_tag_object_message(message: &[u8]) -> Self {
        Self(format!("{:x}", Sha256::digest(message)))
    }

    /// Returns the canonical lowercase SHA-256 rendering.
    pub fn as_str(&self) -> &str {
        &self.0
    }
}

impl fmt::Display for TagAnnotationDigest {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter.write_str(&self.0)
    }
}

/// The complete, remote-only result of comparing an annotated release tag to
/// its immutable expectation. A matching local tag is intentionally absent
/// from this vocabulary: it provides no proof about the configured remote.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum RemoteAnnotatedTagObservation {
    Absent,
    Exact,
    Conflict(RemoteAnnotatedTagConflict),
}

/// The closed reasons a remote tag can fail an exact annotated-tag check.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum RemoteAnnotatedTagConflict {
    /// The remote name resolves to a lightweight tag, which cannot carry the
    /// required annotation.
    LightweightTag,
    /// The tag peels to a commit other than the immutable release source.
    Target { expected: CommitSha, actual: CommitSha },
    /// The annotated tag object's declared target is inconsistent with the
    /// peeled remote ref, so its content cannot be accepted as proof.
    MalformedTarget,
    /// The tag object does not contain the expected annotated-tag header.
    MalformedTagObject,
    /// The tag annotation bytes differ from the release intent.
    Annotation {
        expected: TagAnnotationDigest,
        actual: TagAnnotationDigest,
    },
}

#[derive(Clone, Debug, Error, miette::Diagnostic, PartialEq, Eq)]
#[non_exhaustive]
pub enum VcsError {
    #[error("failed to discover Git repository at `{path}`: {message}")]
    #[diagnostic(code(E050), help("Ensure target directory is inside a valid Git repository."))]
    RepoNotFound { path: PathBuf, message: String },

    #[error("git error: {0}")]
    #[diagnostic(code(E051))]
    Git(String),

    #[error("reference `{ref_name}` was not found")]
    #[diagnostic(code(E052), help("Check if reference or tag exists in local or remote Git refs."))]
    RefNotFound { ref_name: String },

    #[error("tag glob pattern `{pattern}` is not a valid glob: {message}")]
    #[diagnostic(
        code(E053),
        help("Fix the glob syntax (e.g. balance `{{`/`}}` and `[`/`]`) or use a literal tag name.")
    )]
    InvalidGlob { pattern: String, message: String },

    /// Wraps a [`CommandError`] surfaced by the [`ShellGit`] (`CommandRunner`-
    /// shelled) backend -- e.g. the `git` binary itself couldn't be spawned.
    /// Kept `transparent` so callers that only care about the underlying
    /// `CommandError` (most of them, since it's the same error every direct
    /// `CommandRunner::run` call site already surfaces) can match through it.
    #[error(transparent)]
    Command(#[from] CommandError),
}

/// Narrows a [`VcsError`] to the Layer 1 [`CommitWalkError`] vocabulary at
/// the [`CommitWalker`] boundary.
///
/// [`CommitWalkError::Command`] and [`CommitWalkError::RefNotFound`] survive
/// as themselves -- they are the two distinctions consumers branch on. Every
/// other variant is gix- or repository-specific with no Layer 1 equivalent,
/// so it collapses into [`CommitWalkError::Backend`] carrying this error's
/// own `Display` rendering; nothing is lost from the message a user sees.
impl From<VcsError> for CommitWalkError {
    fn from(err: VcsError) -> Self {
        match err {
            VcsError::Command(inner) => CommitWalkError::Command(inner),
            VcsError::RefNotFound { ref_name } => CommitWalkError::RefNotFound { ref_name },
            other => CommitWalkError::Backend {
                message: other.to_string(),
            },
        }
    }
}

/// A commit as produced by a history walk.
///
/// Aliases [`callisto_model::CommitRecord`] rather than redeclaring it, so a
/// walk's output crosses the [`CommitWalker`] seam without a conversion and
/// there is exactly one definition of a commit's shape in the workspace.
pub type GitCommit = CommitRecord;

/// Compiles `pattern` into a [`globset::GlobMatcher`], surfacing a malformed
/// pattern as [`VcsError::InvalidGlob`] rather than letting it silently
/// disable filtering -- which would match every tag, a real correctness
/// risk for release tagging (a malformed tag template could make "last tag"
/// resolution pick an unrelated package's tag). The single shared
/// definition of "how do we compile a tag glob" across both
/// [`GitDataSource`] backends ([`GitRepository::list_tags`],
/// [`ShellGit::list_tags`]) and `callisto-graph`'s `tags::matching_tags`,
/// so all three filter tag names with byte-identical semantics.
pub fn compile_tag_glob(pattern: &str) -> Result<globset::GlobMatcher, VcsError> {
    globset::Glob::new(pattern)
        .map(|g| g.compile_matcher())
        .map_err(|e| VcsError::InvalidGlob {
            pattern: pattern.to_string(),
            message: e.to_string(),
        })
}

/// Whether [`GitDataSource::create_tag`] should let the ambient Git signing
/// configuration (`tag.gpgSign`/`commit.gpgsign`) apply, or force an
/// unsigned tag regardless of it.
///
/// Only [`ShellGit`]'s backend is affected: it shells out to the real `git`
/// binary, which consults process-visible Git config for signing.
/// [`GitRepository`]'s native `gix` backend constructs the tag object
/// directly and never signs either way, so both variants behave identically
/// there.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum TagSignPolicy {
    /// Let the repository's own Git config decide -- the right default for
    /// a human-run `callisto tag`.
    RespectRepoConfig,
    /// Always pass `--no-sign`, regardless of `tag.gpgSign`/`commit.gpgsign`.
    /// Some CI contexts set those globally (for commit signing) with no
    /// tag-signing key available; the durable release executor uses this to
    /// avoid failing there.
    ForceUnsigned,
}

/// Unified git-data access surface covering every operation callisto's
/// release-graph logic needs, independent of *how* the data is sourced.
///
/// Two backends implement this trait:
///
/// - [`GitRepository`] -- native `gix`. Fast, side-effect-free for reads,
///   but unavailable on `wasm32` ([`GitRepository::discover`] always
///   errors there -- gix is excluded from that target's deps).
/// - [`ShellGit`] -- shells out to real `git` via a
///   [`callisto_model::CommandRunner`], so it works everywhere a `git`
///   binary is reachable, including through the `wasm32`/Extism host
///   bridge.
///
/// Callers shouldn't implement or select between these directly; use
/// [`GitAccess::discover`], which tries native `gix` first and falls back
/// to the shell-out, applying the correct per-operation fallback policy
/// (see [`GitAccess`]'s docs).
pub trait GitDataSource {
    /// Returns the commit SHA that `HEAD` currently resolves to.
    fn head_sha(&self) -> Result<CommitSha, VcsError>;

    /// Lists tag names, optionally filtered by `glob` (a [`globset::Glob`]
    /// pattern). Both backends filter with the exact same `globset`
    /// matching semantics, so tag selection is byte-identical regardless of
    /// which one served the request. `None` matches every tag.
    fn list_tags(&self, glob: Option<&str>) -> Result<Vec<TagName>, VcsError>;

    /// Resolves `refname` (tag, branch, or partial/full SHA) to the commit
    /// it points at. An unresolvable ref is *not* an error -- it resolves
    /// to `Ok(None)`, which callers typically treat as "no bound" / "infer
    /// over full history".
    fn resolve_commit(&self, refname: &str) -> Result<Option<CommitSha>, VcsError>;

    /// Lists commits reachable from `HEAD`, down to (exclusive) `since_ref`
    /// when given, filtered to those that touch at least one of
    /// `pathspecs` (an empty slice disables filtering and returns every
    /// commit in the walk). Merge commits are always excluded, matching
    /// `git log --no-merges`.
    ///
    /// Unlike [`Self::resolve_commit`], a `since_ref` that's given but
    /// fails to resolve to a commit *is* an error: silently ignoring it and
    /// walking unbounded history instead of the caller's requested bound
    /// is a correctness bug (e.g. it can re-surface already-released
    /// commits into changelog/severity inference). `since_ref: None` is not
    /// this case -- it's a deliberate request for the full history and
    /// always succeeds.
    fn commits_since(&self, since_ref: Option<&str>, pathspecs: &[PathBuf]) -> Result<Vec<GitCommit>, VcsError>;

    /// Creates the tag `name` at `target_sha`: annotated with `message`
    /// when `Some`, lightweight when `None`. Fails if a ref of that name
    /// already exists.
    ///
    /// `sign` controls whether the ambient Git signing configuration is
    /// allowed to apply -- see [`TagSignPolicy`].
    ///
    /// Writes a git ref, so it requires an [`ApplyPermit`]; a dry run has
    /// none to give and therefore cannot call this at all.
    fn create_tag(
        &self,
        name: &str,
        target_sha: &CommitSha,
        message: Option<&str>,
        sign: TagSignPolicy,
        permit: &ApplyPermit,
    ) -> Result<(), VcsError>;

    /// Force-creates or -moves the floating tag `major_name` to point at
    /// `target_sha`, overwriting any existing ref of that name.
    ///
    /// Writes a git ref, so it requires an [`ApplyPermit`].
    fn create_floating_major(
        &self,
        major_name: &str,
        target_sha: &CommitSha,
        permit: &ApplyPermit,
    ) -> Result<(), VcsError>;

    /// Observes `name` at the configured `remote`, proving both its peeled
    /// commit target and annotated-message digest. This deliberately never
    /// consults a local tag as evidence: an unpushed local match is `Absent`.
    ///
    /// A transport, authentication, malformed-protocol, or command failure
    /// is returned as [`VcsError`], never collapsed into `Absent`.
    fn observe_remote_annotated_tag(
        &self,
        remote: &str,
        name: &TagName,
        target_sha: &CommitSha,
        annotation_digest: &TagAnnotationDigest,
    ) -> Result<RemoteAnnotatedTagObservation, VcsError>;

    /// Pushes the already-created local annotated tag without force and then
    /// re-observes the configured remote using
    /// [`Self::observe_remote_annotated_tag`]. A successful command is not
    /// confirmation; only an `Exact` remote readback is.
    fn push_annotated_tag_and_confirm(
        &self,
        remote: &str,
        name: &TagName,
        target_sha: &CommitSha,
        annotation_digest: &TagAnnotationDigest,
        permit: &ApplyPermit,
    ) -> Result<RemoteAnnotatedTagObservation, VcsError>;
}

/// Wires a [`GitDataSource`] backend up to the Layer 1
/// [`callisto_model::CommitWalker`] contract.
///
        if matches!(sign, crate::TagSignPolicy::ForceUnsigned) {
            args.push("--no-sign");
        }
        args.extend(["--", name, target_sha.as_str()]);
        let output = self.runner.run("git", &args, &self.root)?;
        if !output.success() {
            return Err(VcsError::Git(format!(
                "`git tag` failed in `{}`: {}",
                self.root.display(),
                output.redacted_stderr()
            )));
        }
        Ok(())
    }

    fn create_floating_major(
        &self,
        major_name: &str,
        target_sha: &CommitSha,
        _permit: &ApplyPermit,
    ) -> Result<(), VcsError> {
        let output = self
            .runner
            .run("git", &["tag", "-f", "--", major_name, target_sha.as_str()], &self.root)?;
        if !output.success() {
            return Err(VcsError::Git(format!(
                "`git tag -f` failed in `{}`: {}",
                self.root.display(),
                output.redacted_stderr()
            )));
        }
        Ok(())
    }

    fn observe_remote_annotated_tag(
        &self,
        remote: &str,
        name: &TagName,
        target_sha: &CommitSha,
        annotation_digest: &TagAnnotationDigest,
    ) -> Result<RemoteAnnotatedTagObservation, VcsError> {
        // Ask for both the tag object and its peeled target. `ls-remote`
        // exposes neither a tag annotation nor its object body, so after this
        // cheap absence/target check we fetch only the named tag object with
        // no local ref or FETCH_HEAD update and inspect that exact object.
        let tag_ref = format!("refs/tags/{}", name.as_str());
        let peeled_ref = format!("{tag_ref}^{{}}");
        let ls_remote = self.runner.run(
            "git",
            &["ls-remote", "--tags", "--", remote, &tag_ref, &peeled_ref],
            &self.root,
        )?;
        if !ls_remote.success() {
            return Err(remote_command_error("git ls-remote", &ls_remote));
        }
        let refs = parse_ls_remote_tag_refs(&ls_remote.stdout, &tag_ref, &peeled_ref)?;
        let Some(tag_object) = refs.tag_object else {
            return Ok(RemoteAnnotatedTagObservation::Absent);
        };
        let Some(peeled_target) = refs.peeled_target else {
            return Ok(RemoteAnnotatedTagObservation::Conflict(
                RemoteAnnotatedTagConflict::LightweightTag,
            ));
        };
        if peeled_target != *target_sha {
            return Ok(RemoteAnnotatedTagObservation::Conflict(
                RemoteAnnotatedTagConflict::Target {
                    expected: target_sha.clone(),
                    actual: peeled_target,
                },
            ));
        }

        let fetch = self.runner.run(
            "git",
            &["fetch", "--no-tags", "--no-write-fetch-head", "--", remote, &tag_ref],
            &self.root,
        )?;
        if !fetch.success() {
            return Err(remote_command_error("git fetch", &fetch));
        }
        let tag_object_id = tag_object.as_str();
        let object = self
            .runner
            .run("git", &["cat-file", "-p", "--", tag_object_id], &self.root)?;
        if !object.success() {
            return Err(remote_command_error("git cat-file", &object));
        }
        let (declared_target, actual_annotation) = parse_annotated_tag_object(&object.stdout)?;
        if declared_target != *target_sha {
            return Ok(RemoteAnnotatedTagObservation::Conflict(
                RemoteAnnotatedTagConflict::MalformedTarget,
            ));
        }
        let actual_digest = TagAnnotationDigest::from_tag_object_message(actual_annotation.as_bytes());
        if actual_digest != *annotation_digest {
            return Ok(RemoteAnnotatedTagObservation::Conflict(
                RemoteAnnotatedTagConflict::Annotation {
                    expected: annotation_digest.clone(),
                    actual: actual_digest,
                },
            ));
        }
        Ok(RemoteAnnotatedTagObservation::Exact)
    }

    fn push_annotated_tag_and_confirm(
        &self,
        remote: &str,
        name: &TagName,
        target_sha: &CommitSha,
        annotation_digest: &TagAnnotationDigest,
        _permit: &ApplyPermit,
    ) -> Result<RemoteAnnotatedTagObservation, VcsError> {
        let tag_ref = format!("refs/tags/{}", name.as_str());
        let refspec = format!("{tag_ref}:{tag_ref}");
        let push = self.runner.run("git", &["push", "--", remote, &refspec], &self.root)?;
        if !push.success() {
            // A concurrent producer can turn an initially absent tag into a
            // conflict between observation and push. Re-observe once so that
            // known remote divergence remains typed instead of becoming an
            // opaque command failure; other failures stay VcsError.
            return match self.observe_remote_annotated_tag(remote, name, target_sha, annotation_digest) {
                Ok(RemoteAnnotatedTagObservation::Conflict(conflict)) => {
                    Ok(RemoteAnnotatedTagObservation::Conflict(conflict))
                }
                Ok(_) | Err(_) => Err(remote_command_error("git push", &push)),
            };
        }
        self.observe_remote_annotated_tag(remote, name, target_sha, annotation_digest)
    }
}

struct LsRemoteTagRefs {
    tag_object: Option<CommitSha>,
    peeled_target: Option<CommitSha>,
}

fn parse_ls_remote_tag_refs(stdout: &str, tag_ref: &str, peeled_ref: &str) -> Result<LsRemoteTagRefs, VcsError> {
    let mut tag_object = None;
    let mut peeled_target = None;
    for line in stdout.lines().filter(|line| !line.trim().is_empty()) {
        let Some((object, reference)) = line.split_once('\t') else {
            return Err(VcsError::Git("malformed `git ls-remote` tag output".to_string()));
        };
        let object = CommitSha::parse(object).map_err(|_error| {
            VcsError::Git("`git ls-remote` returned a non-SHA-1 tag object identifier".to_string())
        })?;
        match reference {
            reference if reference == tag_ref => {
                if tag_object.replace(object).is_some() {
                    return Err(VcsError::Git("`git ls-remote` returned duplicate tag refs".to_string()));
                }
            }
            reference if reference == peeled_ref => {
                if peeled_target.replace(object).is_some() {
                    return Err(VcsError::Git(
                        "`git ls-remote` returned duplicate peeled tag refs".to_string(),
                    ));
                }
            }
            _ => {
                return Err(VcsError::Git(
                    "`git ls-remote` returned an unexpected tag ref".to_string(),
                ))
            }
        }
    }
    Ok(LsRemoteTagRefs {
        tag_object,
        peeled_target,
    })
}

fn parse_annotated_tag_object(output: &str) -> Result<(CommitSha, &str), VcsError> {
    let Some((headers, annotation)) = output.split_once("\n\n") else {
        return Err(VcsError::Git(
            "remote tag object has no annotation separator".to_string(),
        ));
    };
    let mut declared_target = None;
    let mut object_type = None;
    for header in headers.lines() {
        if let Some(value) = header.strip_prefix("object ") {
            declared_target =
                Some(CommitSha::parse(value).map_err(|_error| {
                    VcsError::Git("remote annotated tag object has an invalid target".to_string())
                })?);
        } else if let Some(value) = header.strip_prefix("type ") {
            object_type = Some(value);
        }
    }
    if object_type != Some("commit") {
        return Err(VcsError::Git(
            "remote ref did not resolve to an annotated commit tag".to_string(),
        ));
    }
    let declared_target = declared_target
        .ok_or_else(|| VcsError::Git("remote annotated tag object is missing its target header".to_string()))?;
    Ok((declared_target, annotation))
}

fn remote_command_error(command: &str, output: &callisto_model::CommandOutput) -> VcsError {
    VcsError::Git(format!("`{command}` failed: {}", output.redacted_stderr()))
}

/// Parses the `<RECORD_SEP>%H<FIELD_SEP>%B`-formatted `git log` output
/// produced by [`ShellGit::commits_since`] into [`GitCommit`]s, splitting
/// each raw message on its first blank line into `summary`/`body` --
/// mirroring how `gix`'s own commit-message parsing (used by
/// `GitRepository::commits_since_with_pathspec`) splits title from body,
/// so both backends hand callers the same shape.
fn parse_git_log_output(stdout: &str, cwd: &Path) -> Result<Vec<GitCommit>, VcsError> {
    let mut commits = Vec::new();

    for record in stdout.split(RECORD_SEP) {
        // `tformat:`-style `--format=` output (the default when the format
        // string doesn't start with `format:`/`tformat:`) appends a
        // trailing newline after every entry; strip it rather than the
        // message's own content.
        let record = record.trim_end_matches('\n');
        if record.is_empty() {
            continue;
        }

        let Some((sha_str, message)) = record.split_once(FIELD_SEP) else {
            return Err(VcsError::Git(format!(
                "could not parse `git log` output in `{}` into commit records: expected a \
                 `<sha>{FIELD_SEP:?}<message>` record, got: {record:?}",
                cwd.display()
            )));
        };

        let sha = CommitSha::parse(sha_str).map_err(|e| {
            VcsError::Git(format!(
                "could not parse `git log` output in `{}`: invalid commit SHA `{sha_str}`: {e}",
                cwd.display()
            ))
        })?;

        let message = message.replace("\r\n", "\n");
        let (summary, body) = match message.split_once("\n\n") {
            Some((title, rest)) => (title.trim_end().to_string(), Some(rest.to_string())),
            None => (message.trim_end().to_string(), None),
        };

        commits.push(GitCommit { sha, summary, body });
    }

    Ok(commits)
}

#[cfg(test)]
mod tests {

    /// Tests exercise the write primitives directly rather than through a
    /// command handler, so they mint a permit without a dry-run flag to
